def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    left = 0
    while left < n and arr[left] <= arr[(left + 1) % n]:
        left += 1

    if left == n:
        return True

    right = left
    while right < n and arr[right] >= arr[(right - 1) % n]:
        right += 1

    if right == n:
        return True

    return False
