    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Initialize an empty dictionary to store the count of each letter
    count_dict = {}

    # Split the input string into individual letters
    letters = test.split()

    # Iterate over each letter and update the count in the dictionary
    for letter in letters:
        if letter in count_dict:
            count_dict[letter] += 1
        else:
            count_dict[letter] = 1

    # Find the maximum count among all letters
    max_count = max(count_dict.values())

    # Create a dictionary to store the letters with the maximum count
    result = {letter: count for letter, count in count_dict.items() if count == max_count}

    return result

