from collections import deque

def minPath(grid, k):
    N = len(grid)
    dp = [[float('inf')] * N for _ in range(N)]

    # Initialize DP values
    for i in range(N):
        for j in range(N):
            dp[i][j] = 1

    # BFS to initialize DP values
    queue = deque()
    for i in range(N):
        for j in range(N):
            queue.append((i, j))

    while queue:
        i, j = queue.popleft()
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                dp[ni][nj] = min(dp[ni][nj], dp[i][j] + 1)
                queue.append((ni, nj))

    # Find the starting cell with the minimum path length
    start = None
    min_length = float('inf')
    for i in range(N):
        for j in range(N):
            if dp[i][j] < min_length:
                min_length = dp[i][j]
                start = (i, j)

    # BFS to find the minimum path of length k
    queue = deque([(start, [grid[start[0]][start[1]]])])
    while queue:
        i, j, path = queue.popleft()
        if len(path) == k:
            return path
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                candidate_path = path + [grid[ni][nj]]
                queue.append((ni, nj, candidate_path))

    return []

