import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> generateIntegers(int a, int b) {
        List<Integer> evenDigits = new ArrayList<>();
        if (a > b) {
            int temp = a;
            a = b;
            b = temp;
        }

        for (int num = a; num <= b; num++) {
            if (num % 2 == 0) {
                evenDigits.add(num);
            }
        }

        return evenDigits;
    }

    public static void main(String[] args) {
        System.out.println(generateIntegers(2, 8).toString());  // Expected output: [2, 4, 6, 8]
        System.out.println(generateIntegers(8, 2).toString());  // Expected output: [2, 4, 6, 8]
        System.out.println(generateIntegers(10, 14).toString());  // Expected output: []
    }
